# ---------------------------------------------------------------------------
# INP blocks. Attention matches luow23/INP-Former Prototype_Attention and
# Aggregation_Attention: ReLU on L2-normalized prototype attention, softmax
# on the extractor, and no residual from the token being reconstructed.
# ---------------------------------------------------------------------------
def _mlp(dim, ratio, drop):
    hidden = int(dim * ratio)
    return nn.Sequential(
        nn.Linear(dim, hidden),
        nn.GELU(),
        nn.Dropout(drop),
        nn.Linear(hidden, dim),
        nn.Dropout(drop),
    )


class AggregationAttention(nn.Module):
    def __init__(self, dim, num_heads):
        super().__init__()
        if dim % num_heads != 0:
            raise ValueError(f"dim {dim} not divisible by heads {num_heads}")
        self.num_heads = num_heads
        self.scale = (dim // num_heads) ** -0.5
        self.q = nn.Linear(dim, dim, bias=True)
        self.kv = nn.Linear(dim, dim * 2, bias=True)
        self.proj = nn.Linear(dim, dim)

    def forward(self, query, context):
        b, t, c = query.shape
        n = context.shape[1]
        heads = self.num_heads
        hd = c // heads
        q = self.q(query).reshape(b, t, heads, hd).permute(0, 2, 1, 3)
        kv = self.kv(context).reshape(b, n, 2, heads, hd).permute(2, 0, 3, 1, 4)
        k, v = kv[0], kv[1]
        attn = (q @ k.transpose(-2, -1)) * self.scale
        attn = attn.softmax(dim=-1)
        out = (attn @ v).transpose(1, 2).reshape(b, t, c)
        return self.proj(out)


class PrototypeAttention(nn.Module):
    def __init__(self, dim, num_heads):
        super().__init__()
        if dim % num_heads != 0:
            raise ValueError(f"dim {dim} not divisible by heads {num_heads}")
        self.num_heads = num_heads
        self.learn_scale = nn.Parameter(
            torch.ones(num_heads, 1, 1))
        self.q = nn.Linear(dim, dim, bias=True)
        self.kv = nn.Linear(dim, dim * 2, bias=True)
        self.proj = nn.Linear(dim, dim)

    def forward(self, tokens, prototypes):
        b, n, c = tokens.shape
        m = prototypes.shape[1]
        heads = self.num_heads
        hd = c // heads
        q = self.q(tokens).reshape(b, n, heads, hd).permute(0, 2, 1, 3)
        kv = self.kv(prototypes).reshape(b, m, 2, heads, hd).permute(
            2, 0, 3, 1, 4)
        k, v = kv[0], kv[1]
        q = F.normalize(q, dim=-1)
        k = F.normalize(k, dim=-1)
        attn = F.relu(
            (q @ k.transpose(-2, -1)) * self.learn_scale)
        out = (attn @ v).transpose(1, 2).reshape(b, n, c)
        return self.proj(out)


class AggregationBlock(nn.Module):
    def __init__(self, dim, num_heads):
        super().__init__()
        self.norm_q = nn.LayerNorm(dim, eps=1e-8)
        self.norm_kv = nn.LayerNorm(dim, eps=1e-8)
        self.attn = AggregationAttention(dim, num_heads)
        self.norm2 = nn.LayerNorm(dim, eps=1e-8)
        self.mlp = _mlp(dim, 4.0, 0.0)

    def forward(self, query, context):
        query = query + self.attn(self.norm_q(query), self.norm_kv(context))
        query = query + self.mlp(self.norm2(query))
        return query


class PrototypeBlock(nn.Module):
    def __init__(self, dim, num_heads):
        super().__init__()
        self.norm_q = nn.LayerNorm(dim, eps=1e-8)
        self.norm_p = nn.LayerNorm(dim, eps=1e-8)
        self.attn = PrototypeAttention(dim, num_heads)
        self.norm2 = nn.LayerNorm(dim, eps=1e-8)
        self.mlp = _mlp(dim, 4.0, 0.0)

    def forward(self, tokens, prototypes):
        # Official Prototype_Block replaces tokens; it does not add them back.
        hidden = self.attn(self.norm_q(tokens), self.norm_p(prototypes))
        hidden = hidden + self.mlp(self.norm2(hidden))
        return hidden


class INPLocalizer(nn.Module):
    def __init__(self, dim=768, num_heads=12, depth=DECODER_DEPTH,
                 prototypes=PROTO_NUM):
        super().__init__()
        self.dim = dim
        self.prototype = nn.Parameter(
            torch.randn(prototypes, dim))
        self.aggregation = nn.ModuleList(
            [AggregationBlock(dim, num_heads)])
        self.bottleneck = nn.ModuleList(
            [_mlp(dim, 4.0, 0.0)])
        self.decoder = nn.ModuleList(
            [PrototypeBlock(dim, num_heads) for _ in range(depth)])

    def reconstruct(self, groups, cls=None):
        """groups: [B, 2, C, H, W]. cls: [B, 2, C] or None.

        Returns encoder group maps, decoder group maps, coherence loss,
        and the min cosine-distance map to the extracted prototypes.
        """
        b, g, c, h, w = groups.shape
        if g != 2 or c != self.dim:
            raise RuntimeError(f"expected [B,2,{self.dim},H,W], got {tuple(groups.shape)}")
        if len(self.decoder) != 8:
            raise RuntimeError("decoder grouping assumes 8 layers")
        tok = groups.permute(0, 1, 3, 4, 2).contiguous()
        if cls is not None:
            tok = tok - cls[:, :, None, None, :]
        targets = [tok[:, i].permute(0, 3, 1, 2).contiguous() for i in range(2)]
        all_mean = 0.5 * (tok[:, 0] + tok[:, 1])
        tokens = all_mean.reshape(b, h * w, c)
        proto = self.prototype.unsqueeze(0).expand(b, -1, -1)
        for blk in self.aggregation:
            proto = blk(proto, tokens)
        coherence = _gather_loss(tokens, proto)
        hidden = tokens
        for blk in self.bottleneck:
            hidden = blk(hidden)
        decoded = []
        for blk in self.decoder:
            hidden = blk(hidden, proto)
            decoded.append(hidden)
        decoded = decoded[::-1]
        de_groups = []
        for idxs in ((0, 1, 2, 3), (4, 5, 6, 7)):
            stacked = torch.stack([decoded[i] for i in idxs], dim=0).mean(0)
            de_groups.append(stacked.transpose(1, 2).reshape(b, c, h, w).contiguous())
        dist = _min_cosine_distance(tokens, proto).reshape(b, h, w)
        return targets, de_groups, coherence, dist

    def loss(self, groups, cls=None):
        targets, decoded, coherence, _dist = self.reconstruct(groups, cls)
        recon = _global_cosine_adaptive(targets, decoded, SOFT_GAMMA)
        total = recon + COHERENCE_WEIGHT * coherence
        return total, {
            "recon": float(recon.detach()),
            "coherence": float(coherence.detach()),
            "total": float(total.detach()),
        }

    def score(self, groups, cls=None):
        targets, decoded, _coherence, dist = self.reconstruct(groups, cls)
        parts = []
        for src, hat in zip(targets, decoded):
            parts.append(1.0 - F.cosine_similarity(
                src, hat, dim=1))
        recon = torch.stack(parts, dim=0).mean(dim=0)
        return recon, dist


def _gather_loss(tokens, prototypes):
    dist = 1.0 - F.cosine_similarity(
        tokens.unsqueeze(2), prototypes.unsqueeze(1), dim=-1)
    return dist.min(dim=2).values.mean()


def _min_cosine_distance(tokens, prototypes):
    dist = 1.0 - F.cosine_similarity(
        tokens.unsqueeze(2), prototypes.unsqueeze(1), dim=-1)
    return dist.min(dim=2).values


def _modify_grad(grad, factor):
    return grad * factor.expand_as(grad)


def _global_cosine_adaptive(sources, decoded, gamma):
    cos = nn.CosineSimilarity()
    total = 0.0
    for src, hat in zip(sources, decoded):
        src_det = src.detach()
        with torch.no_grad():
            point = (1.0 - cos(src_det, hat).unsqueeze(1)).detach()
            mean = point.mean().clamp_min(1e-6)
            factor = (point / mean).pow(gamma)
        flat_src = src_det.reshape(src_det.shape[0], -1)
        flat_hat = hat.reshape(hat.shape[0], -1)
        total = total + (1.0 - cos(flat_src, flat_hat)).mean()
        hat.register_hook(lambda g, f=factor: _modify_grad(g, f))
    return total / len(sources)


def init_localizer(module, seed):
    torch.manual_seed(seed)
    with torch.no_grad():
        module.prototype.copy_(torch.randn_like(module.prototype))
    for sub in module.modules():
        if isinstance(sub, torch.nn.Linear):
            torch.nn.init.trunc_normal_(sub.weight, std=0.01, a=-0.03, b=0.03)
            if sub.bias is not None:
                torch.nn.init.zeros_(sub.bias)
        elif isinstance(sub, torch.nn.LayerNorm):
            torch.nn.init.ones_(sub.weight)
            torch.nn.init.zeros_(sub.bias)


def knn_distance(tokens, bank):
    """tokens [B,N,C], bank [K,C], both will be L2-normalized. Returns [B,N]."""
    q = F.normalize(tokens, dim=-1)
    ref = F.normalize(bank, dim=-1)
    sim = q @ ref.transpose(0, 1)
    return 1.0 - sim.max(dim=-1).values


# ---------------------------------------------------------------------------
# feature extraction
# ---------------------------------------------------------------------------
def shallow_outlier(tokens, radius=1):
    """tokens [B, N, C] on a square grid.

    Score is 1 minus the maximum cosine similarity to any token outside the
    Chebyshev neighborhood. No parameters are trained.
    """
    b, n, _c = tokens.shape
    side = int(math.sqrt(n))
    if side * side != n:
        raise RuntimeError(f"shallow token count {n} is not a square")
    flat = F.normalize(tokens, dim=-1)
    sim = flat @ flat.transpose(1, 2)
    coord = torch.arange(side, device=tokens.device)
    yy = coord.view(side, 1, 1, 1)
    xx = coord.view(1, side, 1, 1)
    y2 = coord.view(1, 1, side, 1)
    x2 = coord.view(1, 1, 1, side)
    local = ((yy - y2).abs() <= radius) & ((xx - x2).abs() <= radius)
    sim = sim.masked_fill(local.reshape(1, n, n), -1.0)
    return (1.0 - sim.max(dim=-1).values).reshape(b, side, side)


def encode_hi(model, x):
    """One frozen encoder/decoder pass.

    Returns the high-res reconstruction map, two fused groups [B,2,768,H,W],
    their class tokens [B,2,768], and a shallow within-image outlier map
    from the mean of blocks 0 and 1. Those two blocks are not part of the
    prototype targets.
    """
    encoder = model.encoder
    tokens = encoder.prepare_tokens(x)
    en_list = []
    early = []
    for i, blk in enumerate(encoder.blocks):
        if i > model.target_layers[-1]:
            break
        with torch.no_grad():
            tokens = blk(tokens)
        if i in (0, 1):
            early.append(tokens)
        if i in model.target_layers:
            en_list.append(tokens)
    reg = int(getattr(encoder, "num_register_tokens", 0))
    side = int(math.sqrt(en_list[0].shape[1] - 1 - reg))
    if side * side != en_list[0].shape[1] - 1 - reg:
        raise RuntimeError("token grid is not square")

    groups, classes = [], []
    for idxs in ((0, 1, 2, 3), (4, 5, 6, 7)):
        stacked = torch.stack([en_list[i] for i in idxs], dim=0).mean(dim=0)
        classes.append(stacked[:, 0, :])
        patch = stacked[:, 1 + reg:, :]
        groups.append(patch.permute(0, 2, 1).reshape(
            x.shape[0], -1, side, side).contiguous())
    groups = torch.stack(groups, dim=1)
    classes = torch.stack(classes, dim=1)
    if len(early) != 2:
        raise RuntimeError(f"expected encoder blocks 0 and 1, got {len(early)}")
    early_mean = torch.stack(early, dim=0).mean(dim=0)
    early_patch = early_mean[:, 1 + reg:, :]
    shallow = shallow_outlier(early_patch)

    feat = model.fuse_feature(en_list)
    for blk in model.bottleneck:
        feat = blk(feat)
    de_list = []
    for blk in model.decoder:
        feat = blk(feat, attn_mask=None)
        de_list.append(feat)
    de_list = de_list[::-1]
    en = [model.fuse_feature([en_list[idx] for idx in idxs])
          for idxs in model.fuse_layer_encoder]
    de = [model.fuse_feature([de_list[idx] for idx in idxs])
          for idxs in model.fuse_layer_decoder]
    en = [e[:, 1 + reg:, :] for e in en]
    de = [d[:, 1 + reg:, :] for d in de]
    en = [e.permute(0, 2, 1).reshape(x.shape[0], -1, side, side).contiguous()
          for e in en]
    de = [d.permute(0, 2, 1).reshape(x.shape[0], -1, side, side).contiguous()
          for d in de]
    amap, _ = s12.cal_anomaly_maps(en, de, x.shape[-1])
    return amap, groups, classes, shallow


def b0_and_features(model, x_base, x_hi, gaussian):
    base = s12.postprocess(
        s12.global_map_chunked(model, x_base, s12.BASE_BATCH_EFF), gaussian)
    hi_raw, groups, cls, shallow = encode_hi(model, x_hi)
    hi = s12.postprocess(hi_raw, gaussian)
    fused = 0.5 * base + 0.5 * hi
    b0 = s12.guided_filter(s12.guide_from_hi(x_hi), fused)
    return {"base": base, "b0": b0, "groups": groups, "cls": cls,
            "shallow": shallow}


def to_maps(raw_hw, gaussian):
    """[B,H,W] token map -> smoothed 256 map [B,1,256,256]."""
    x = raw_hw.unsqueeze(1).float()
    return s12.postprocess(x, gaussian)


# ---------------------------------------------------------------------------
# cache, kNN bank, training
# ---------------------------------------------------------------------------
def cache_train(model, items, splits, hi_tf, device, cache_dir):
    os.makedirs(cache_dir, exist_ok=True)
    from PIL import Image
    index = []
    started = time.time()
    model.eval()
    with torch.no_grad():
        for item in items:
            paths = splits[item]["train"]
            for p in paths:
                digest = hashlib.sha256(p.encode("utf-8")).hexdigest()[:16]
                file = os.path.join(cache_dir, f"{item}_{digest}.npz")
                if not os.path.isfile(file):
                    pil = Image.open(p).convert("RGB")
                    x = hi_tf(pil).unsqueeze(0).to(device)
                    _amap, groups, cls, _shallow = encode_hi(model, x)
                    np.savez(file,
                             groups=groups[0].half().cpu().numpy(),
                             cls=cls[0].half().cpu().numpy())
                    del x, groups, cls
                index.append({"class": item, "path": p, "file": file})
            log(f"cache {item}: {len(paths)} train images")
    log(f"cache done n={len(index)} seconds={time.time() - started:.1f}")
    return index


def load_cached(entries, ids, device):
    groups, classes = [], []
    for i in ids:
        with np.load(entries[int(i)]["file"]) as z:
            groups.append(z["groups"])
            classes.append(z["cls"])
    g = torch.from_numpy(np.stack(groups)).to(device=device, dtype=torch.float32)
    c = torch.from_numpy(np.stack(classes)).to(device=device, dtype=torch.float32)
    return g, c


def build_knn_bank(entries, items, device, per_class=KNN_PER_CLASS, seed=SEED):
    """Unified bank of recentered all-layer-mean tokens. Class id is not a query key."""
    rng = np.random.default_rng(seed)
    chosen = []
    by_class = {}
    for i, row in enumerate(entries):
        by_class.setdefault(row["class"], []).append(i)
    for item in items:
        ids = by_class[item]
        take = min(per_class, len(ids) * s12.GRID * s12.GRID)
        # Sample images uniformly, then one random patch each time, with replacement
        # across patches but a hard cap of `per_class` vectors.
        pick_img = rng.choice(ids, size=take, replace=True)
        pick_xy = rng.integers(0, s12.GRID, size=(take, 2))
        chunks = []
        order = np.argsort(pick_img, kind="mergesort")
        pick_img = pick_img[order]
        pick_xy = pick_xy[order]
        start = 0
        while start < take:
            img_id = int(pick_img[start])
            stop = start
            while stop < take and int(pick_img[stop]) == img_id:
                stop += 1
            g, c = load_cached(entries, [img_id], device)
            tok = g[0] - c[0][:, None, None, :]
            mean = 0.5 * (tok[0] + tok[1])  # [C,H,W]
            mean = mean.permute(1, 2, 0)
            xy = pick_xy[start:stop]
            vec = mean[xy[:, 0], xy[:, 1]]
            chunks.append(vec.detach())
            start = stop
        chosen.append(torch.cat(chunks, dim=0))
        log(f"knn bank {item}: {take}")
    bank = torch.cat(chosen, dim=0).contiguous()
    return F.normalize(bank, dim=-1)


def train_localizer(module, entries, device, recenter, epochs, batch, seed):
    init_localizer(module, seed)
    module.to(device)
    opt = torch.optim.AdamW(module.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)
    n = len(entries)
    history = []
    rng = np.random.default_rng(seed)
    for epoch in range(epochs):
        module.train()
        order = rng.permutation(n)
        losses = []
        t0 = time.time()
        for start in range(0, n, batch):
            ids = order[start:start + batch]
            groups, cls = load_cached(entries, ids, device)
            opt.zero_grad(set_to_none=True)
            loss, parts = module.loss(groups, cls if recenter else None)
            if not math.isfinite(parts["total"]):
                raise RuntimeError(f"non-finite loss at epoch {epoch + 1}: {parts}")
            loss.backward()
            torch.nn.utils.clip_grad_norm_(module.parameters(), GRAD_CLIP)
            opt.step()
            losses.append(parts["total"])
        row = {"epoch": epoch + 1, "loss": float(np.mean(losses)),
               "seconds": float(time.time() - t0), "recenter": bool(recenter)}
        history.append(row)
        log(f"train recenter={recenter} epoch {epoch + 1}/{epochs} "
            f"loss={row['loss']:.4f} seconds={row['seconds']:.1f}")
    module.eval()
    return history


# ---------------------------------------------------------------------------
# evaluation
# ---------------------------------------------------------------------------
def score_batch(model, inp, inp_raw, bank, x_base, x_hi, gaussian):
    with torch.no_grad():
        raw = b0_and_features(model, x_base, x_hi, gaussian)
        groups = raw["groups"]
        cls = raw["cls"]
        recon, dist = inp.score(groups, cls)
        recon_raw, _dist_raw = inp_raw.score(groups, None)
        b, _g, c, h, w = groups.shape
        tok = groups.permute(0, 1, 3, 4, 2) - cls[:, :, None, None, :]
        mean = 0.5 * (tok[:, 0] + tok[:, 1]).reshape(b, h * w, c)
        knn = knn_distance(mean, bank).reshape(b, h, w)
        maps = {
            "b0": raw["b0"],
            "base": raw["base"],
            "inp": to_maps(recon, gaussian),
            "inp_raw": to_maps(recon_raw, gaussian),
            "inp_dist": to_maps(dist, gaussian),
            "knn": to_maps(knn, gaussian),
            "shallow": to_maps(raw["shallow"], gaussian),
        }
    return maps


def score_resilient(model, inp, inp_raw, bank, img, his, gaussian):
    """Run a batch, and split it if the 672 forward runs out of memory."""
    try:
        return score_batch(model, inp, inp_raw, bank, img, his, gaussian)
    except RuntimeError as exc:
        if "out of memory" not in str(exc).lower() or img.shape[0] == 1:
            raise
        torch.cuda.empty_cache()
        log(f"WARNING: score OOM at batch {img.shape[0]}; retrying one image")
        parts = [score_batch(model, inp, inp_raw, bank, img[i:i + 1],
                             his[i:i + 1], gaussian)
                 for i in range(img.shape[0])]
        return {k: torch.cat([p[k] for p in parts], dim=0) for k in parts[0]}


def fuse_maps(maps, stats):
    out = {"b0": maps["b0"]}
    normalized = {"b0": s12.normalize_map(maps["b0"], stats["b0"])}
    for name in HEAD_VARIANTS:
        normalized[name] = s12.normalize_map(maps[name], stats[name])
        out[name] = normalized[name]
    for fused, src in FUSION.items():
        out[fused] = (s12.FUSION_BASE_WEIGHT * normalized["b0"]
                      + s12.FUSION_HEAD_WEIGHT * normalized[src])
    return out


def evaluate_class(item, dataset, model, inp, inp_raw, bank, gaussian,
                   stats, device):
    loader = s12.DataLoader(
        dataset, batch_size=s12.EVAL_BATCH, shuffle=False, num_workers=0)
    buckets = {v: [] for v in VARIANTS}
    scores = {v: [] for v in VARIANTS}
    base_scores, gt_buf, labels, paths = [], [], [], []
    started = time.time()
    with torch.no_grad():
        for bi, batch in enumerate(loader):
            img, gt, label, path, his = batch
            img = img.to(device)
            his = his.to(device)
            raw = score_resilient(model, inp, inp_raw, bank, img, his, gaussian)
            maps = fuse_maps(raw, stats)
            base_scores.extend(s12.top1pct(raw["base"]).cpu().numpy().tolist())
            for name in VARIANTS:
                buckets[name].append(maps[name].cpu())
                scores[name].extend(s12.top1pct(maps[name]).cpu().numpy().tolist())
            gt256 = torch.nn.functional.interpolate(
                gt.float(), size=256, mode="nearest").bool()
            if gt256.shape[1] > 1:
                gt256 = gt256.max(dim=1, keepdim=True).values
            gt_buf.append(gt256.cpu())
            labels.extend(label.numpy().tolist())
            paths.extend(list(path))
            if bi == 0 or (bi + 1) == len(loader) or (bi + 1) % 10 == 0:
                log(f"  {item} batch {bi + 1}/{len(loader)} images={len(labels)}")
    gt_np = torch.cat(gt_buf, dim=0)[:, 0].numpy()
    gt_np = (gt_np > 0.5).astype(np.uint8)
    labels_np = np.asarray(labels, dtype=np.int64)
    regions = s12.label_regions(gt_np)
    variants = {}
    preds = {}
    for name in VARIANTS:
        pr = torch.cat(buckets[name], dim=0)[:, 0].numpy().astype(np.float32)
        preds[name] = pr
        img_metrics = s12.image_metrics_from_scores(
            labels_np, np.asarray(scores[name]))
        variants[name] = s12.summarize_variant(
            gt_np, pr, labels_np, img_metrics, regions)
    result = {
        "class": item,
        "n_test": int(len(labels_np)),
        "n_normal": int((labels_np == 0).sum()),
        "n_anomaly": int((labels_np == 1).sum()),
        "n_gt_positive_pixels": int(gt_np.sum()),
        "calibration": stats,
        "image_metrics_original_base": s12.image_metrics_from_scores(
            labels_np, np.asarray(base_scores, dtype=np.float64)),
        "variants": {
            name: {"metrics": variants[name]["metrics"],
                   "recall": variants[name]["recall"],
                   "per_image_ap": [
                       (float(x) if np.isfinite(x) else None)
                       for x in variants[name]["per_image_ap"]]}
            for name in VARIANTS
        },
        "seconds": float(time.time() - started),
    }
    arrays = {"gt": gt_np, "labels": labels_np,
              "paths": np.asarray(paths, dtype=str),
              "preds": preds,
              "scores": {k: np.asarray(v, dtype=np.float64) for k, v in scores.items()}}
    return result, arrays


def calibrate(items, splits, model, inp, inp_raw, bank, base_tf, hi_tf,
              gaussian, device):
    from PIL import Image
    out = {}
    for item in items:
        paths = splits[item]["calib"]
        values = {k: [] for k in ("b0",) + HEAD_VARIANTS}
        with torch.no_grad():
            for start in range(0, len(paths), s12.EVAL_BATCH):
                chunk = paths[start:start + s12.EVAL_BATCH]
                xb, xh = [], []
                for p in chunk:
                    pil = Image.open(p).convert("RGB")
                    xb.append(base_tf(pil))
                    xh.append(hi_tf(pil))
                raw = score_resilient(model, inp, inp_raw, bank,
                                      torch.stack(xb).to(device),
                                      torch.stack(xh).to(device), gaussian)
                for k in values:
                    values[k].append(raw[k].detach().float().cpu().numpy())
        stats = {k: s12.calibration_stats(np.concatenate(v, axis=0))
                 for k, v in values.items()}
        out[item] = stats
        log("calibration " + item + " " + " ".join(
            f"{k}={stats[k]['scale']:.4f}" for k in ("b0", "inp", "knn")))
    return out


def aggregate(per_class, items):
    def metric(name, key):
        return s12.finite_mean(
            [per_class[it]["variants"][name]["metrics"].get(key) for it in items])

    mean = {name: {k: metric(name, k) for k in s12.METRIC_KEYS} for name in VARIANTS}
    pairs = [("b0_inp", "b0"), ("b0_knn", "b0"), ("b0_inp", "b0_knn"),
             ("inp", "b0"), ("inp_raw", "inp"), ("knn", "b0"),
             ("inp_dist", "inp"), ("shallow", "inp"), ("shallow", "b0")]
    deltas = {}
    for a, b in pairs:
        per = {it: (per_class[it]["variants"][a]["metrics"]["P-AP"]
                    - per_class[it]["variants"][b]["metrics"]["P-AP"])
               for it in items}
        deltas[f"{a} - {b}"] = {
            "P-AP": mean[a]["P-AP"] - mean[b]["P-AP"],
            "P-AP-image": mean[a]["P-AP-image"] - mean[b]["P-AP-image"],
            "per_class_P-AP": per,
        }
    gain = deltas["b0_inp - b0"]["P-AP"]
    versus_knn = deltas["b0_inp - b0_knn"]["P-AP"]
    per = deltas["b0_inp - b0"]["per_class_P-AP"]
    n_ok = sum(1 for v in per.values() if v >= 0.0)
    min_delta = min(per.values()) if per else float("nan")
    passed = bool(
        np.isfinite(gain) and gain >= 0.01
        and np.isfinite(versus_knn) and versus_knn > 0.0
        and n_ok >= 3
        and np.isfinite(min_delta) and min_delta >= -0.02)
    secondary = None
    if np.isfinite(mean["b0_inp"]["P-AP"]):
        secondary = {
            "stage12_b0_c1_macro": STAGE12_B0_C1_MACRO,
            "b0_inp_minus_stage12_b0_c1": mean["b0_inp"]["P-AP"] - STAGE12_B0_C1_MACRO,
            "note": "not part of the pass rule; the conv head is not retrained",
        }
    return {
        "mean": mean,
        "deltas": deltas,
        "entry_condition": {
            "b0_inp_minus_b0_P-AP": gain,
            "b0_inp_minus_b0_knn_P-AP": versus_knn,
            "classes_with_nonnegative_delta": int(n_ok),
            "classes_total": len(items),
            "min_per_class_delta": min_delta,
            "per_image_P-AP_direction": deltas["b0_inp - b0"]["P-AP-image"],
            "thresholds": {"P-AP_gain_min": 0.01, "must_exceed_b0_knn": True,
                           "min_nonnegative_classes": 3,
                           "max_allowed_class_drop": 0.02},
            "passed": passed,
        },
        "secondary_vs_stage12_conv_fusion": secondary,
        "mechanism_read": _mechanism_read(deltas, gain),
    }


def _mechanism_read(deltas, fusion_gain):
    """Interpretation written before any stage-13 test score existed.

    `entry_condition.passed` stays the spending gate from the original plan.
    A pass is not a claim that within-image prototypes work. Stage 12 already
    showed that 0.75/0.25 fusion of a bad head can clear +1.4pp.
    """
    inp_b0 = deltas["inp - b0"]["per_class_P-AP"]
    shallow_inp = deltas["shallow - inp"]["per_class_P-AP"]
    return {
        "formal_passed_is_a_spending_gate": True,
        "fusion_gain_clears_stage12_artifact_band": (
            bool(fusion_gain >= 0.02) if np.isfinite(fusion_gain) else False),
        "artifact_band": 0.02,
        "object_collapse_line": -0.10,
        "screw_inp_minus_b0": inp_b0.get("screw"),
        "capsule_inp_minus_b0": inp_b0.get("capsule"),
        "screw_shallow_minus_inp": shallow_inp.get("screw"),
        "capsule_shallow_minus_inp": shallow_inp.get("capsule"),
        "inp_raw_minus_inp": deltas["inp_raw - inp"]["P-AP"],
    }


# ---------------------------------------------------------------------------
# self-test
# ---------------------------------------------------------------------------
def run_self_test():
    checks = 0

    def ok(cond, msg):
        nonlocal checks
        if not cond:
            raise AssertionError(msg)
        checks += 1

    # No skip from the reconstructed token: zeroed block emits zeros.
    blk = PrototypeBlock(32, 4)
    for p in blk.parameters():
        p.data.zero_()
    tokens = torch.randn(2, 16, 32)
    out = blk(tokens, torch.randn(2, 4, 32))
    ok(torch.allclose(out, torch.zeros_like(out), atol=1e-6),
       "prototype block has no token residual")

    # Extractor does keep a residual, so zeroed linears/norms still return the query
    # only when norms are identity and linears are zero: output equals query.
    agg = AggregationBlock(32, 4)
    for sub in agg.modules():
        if isinstance(sub, torch.nn.Linear):
            sub.weight.data.zero_()
            if sub.bias is not None:
                sub.bias.data.zero_()
    query = torch.randn(2, 4, 32)
    kept = agg(query, torch.randn(2, 16, 32))
    ok(torch.allclose(kept, query, atol=1e-5), "extractor keeps the query residual")

    net = INPLocalizer(dim=32, num_heads=4, depth=8, prototypes=4)
    init_localizer(net, SEED)
    base = torch.randn(4, 2, 32, 4, 4)
    cls = torch.randn(4, 2, 32)
    opt = torch.optim.AdamW(net.parameters(), lr=1e-3, weight_decay=1e-4)
    losses = []
    for _ in range(25):
        opt.zero_grad(set_to_none=True)
        loss, parts = net.loss(base, cls)
        ok(math.isfinite(parts["total"]), "toy loss finite")
        loss.backward()
        torch.nn.utils.clip_grad_norm_(net.parameters(), GRAD_CLIP)
        opt.step()
        losses.append(parts["total"])
    ok(losses[-1] < losses[0], f"toy loss should fall, {losses[0]:.4f} -> {losses[-1]:.4f}")
    net.eval()
    with torch.no_grad():
        err, dist = net.score(base[:2], cls[:2])
    ok(err.shape == (2, 4, 4) and dist.shape == (2, 4, 4), "score shapes")

    bank = torch.nn.functional.normalize(torch.tensor([[1.0, 0.0], [0.0, 1.0]]), dim=-1)
    query = torch.tensor([[[1.0, 0.0], [1.0, 1.0]]])
    dist_k = knn_distance(query, bank)
    ok(abs(float(dist_k[0, 0])) < 1e-5, "stored direction has zero knn distance")
    ok(float(dist_k[0, 1]) > 0.2, "unseen direction has positive knn distance")

    # Entry rule on a synthetic report. One class drops 3pp -> fail.
    fake_items = ["a", "b", "c", "d"]
    def fake(deltas):
        per = {}
        for it, d in zip(fake_items, deltas):
            per[it] = {"variants": {"b0_inp": {"metrics": {"P-AP": 0.60 + d,
                                                           "P-AP-image": 0.60 + d}},
                                    "b0": {"metrics": {"P-AP": 0.60, "P-AP-image": 0.60}},
                                    "b0_knn": {"metrics": {"P-AP": 0.605,
                                                           "P-AP-image": 0.605}},
                                    "inp": {"metrics": {"P-AP": 0.50, "P-AP-image": 0.50}},
                                    "inp_raw": {"metrics": {"P-AP": 0.49, "P-AP-image": 0.49}},
                                    "inp_dist": {"metrics": {"P-AP": 0.48, "P-AP-image": 0.48}},
                                    "knn": {"metrics": {"P-AP": 0.47, "P-AP-image": 0.47}},
                                    "shallow": {"metrics": {"P-AP": 0.55,
                                                            "P-AP-image": 0.55}}}}
            for key in s12.METRIC_KEYS:
                for name in VARIANTS:
                    per[it]["variants"][name]["metrics"].setdefault(key, 0.0)
        return per
    good = aggregate(fake((0.02, 0.02, 0.02, 0.011)), fake_items)
    ok(good["entry_condition"]["passed"] is True, "synthetic pass")
    bad = aggregate(fake((0.03, 0.03, 0.03, -0.03)), fake_items)
    ok(bad["entry_condition"]["passed"] is False, "a 3pp drop must fail")
    tie = aggregate(fake((0.02, 0.02, 0.02, 0.02)), fake_items)
    # b0_knn is 0.605, b0_inp is 0.62, still above. Build an explicit tie by
    # raising knn inside fake() is fixed; check the comparator with equal maps.
    equal = fake((0.005, 0.005, 0.005, 0.005))
    for it in fake_items:
        equal[it]["variants"]["b0_knn"]["metrics"]["P-AP"] = \
            equal[it]["variants"]["b0_inp"]["metrics"]["P-AP"]
    tied = aggregate(equal, fake_items)
    ok(tied["entry_condition"]["passed"] is False, "tie with knn must fail")
    ok(tie["entry_condition"]["passed"] is True, "2pp over both references passes")

    # Recentering is exactly a broadcast subtraction.
    groups = torch.ones(1, 2, 4, 2, 2)
    cls = torch.zeros(1, 2, 4)
    cls[0, 0, :] = 0.25
    tok = groups.permute(0, 1, 3, 4, 2) - cls[:, :, None, None, :]
    ok(abs(float(tok[0, 0].mean()) - 0.75) < 1e-6, "recentered group 0")
    ok(abs(float(tok[0, 1].mean()) - 1.0) < 1e-6, "untouched group 1")

    grid = torch.zeros(1, 16, 4)
    grid[..., 0] = 1.0
    grid[0, 5, :] = 0.0
    grid[0, 5, 1] = 1.0
    odd = shallow_outlier(grid)
    ok(float(odd.view(-1)[5]) > 0.9, "odd shallow token scores high")
    ok(float(odd.view(-1)[0]) < 0.05, "repeated shallow token scores low")
    import base64
    import hashlib
    import zlib
    sibling = os.path.abspath(os.path.join(
        os.path.dirname(__file__), "..", "stage12", "masked_recon_v12.py"))
    vendored = zlib.decompress(base64.b64decode(_STAGE12_ZLIB))
    with open(sibling, "rb") as handle:
        on_disk = handle.read()
    ok(hashlib.sha256(vendored).digest() == hashlib.sha256(on_disk).digest(),
       "vendored stage12 matches the sibling file")

    log(f"self-test passed checks={checks}")
    return checks


# ---------------------------------------------------------------------------
# main
# ---------------------------------------------------------------------------
def main():
    global OUT, LOG_PATH
    ap = argparse.ArgumentParser()
    ap.add_argument("--self-test", action="store_true")
    ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--classes", type=str, default="leather,capsule,grid,screw")
    ap.add_argument("--out", type=str, default=None)
    ap.add_argument("--epochs", type=int, default=EPOCHS)
    ap.add_argument("--train-batch", type=int, default=TRAIN_BATCH)
    ap.add_argument("--limit-test", type=int, default=0)
    args = ap.parse_args()

    if args.self_test:
        s12.LOG_PATH = None
        run_self_test()
        return

    OUT = args.out or ("/kaggle/working" if os.path.isdir("/kaggle/working")
                       else os.path.join(os.path.dirname(__file__), "..", "..",
                                         "stage13-local"))
    OUT = os.path.abspath(OUT)
    os.makedirs(OUT, exist_ok=True)
    LOG_PATH = os.path.join(OUT, "stage13.log")
    s12.LOG_PATH = LOG_PATH
    log(f"=== {SLUG} start ===")
    run_self_test()

    s12.prepare_environment()
    device = "cuda:0" if torch.cuda.is_available() else "cpu"
    if device == "cpu" and not args.smoke:
        raise RuntimeError("stage 13 result run needs a GPU")
    s12.BASE_BATCH_EFF = 1
    s12.HI_BATCH_EFF = 1
    s12.EVAL_BATCH = 1
    s12.DEVICE = device
    torch.manual_seed(SEED)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(SEED)

    s12.find_checkpoints()
    base_sha = s12.sha256_file(s12.BASE_CKPT)
    log(f"base sha256={base_sha}")
    model = s12.build_model(device)
    state = s12.load_ckpt(model, s12.BASE_CKPT, device)
    model.eval()
    for p in model.parameters():
        p.requires_grad_(False)
    log(f"checkpoint iter={state.get('iter')} device={device}")

    base_tf, gt_tf = s12.get_data_transforms(s12.BASE_RESIZE, s12.BASE_CROP)
    hi_tf = s12.get_data_transforms(s12.HI_RESIZE, s12.HI_CROP)[0]
    gaussian = s12.get_gaussian_kernel(kernel_size=s12.GAUSSIAN_KERNEL,
                                       sigma=s12.GAUSSIAN_SIGMA).to(device)

    items = [c.strip() for c in args.classes.split(",") if c.strip()]
    epochs = 1 if args.smoke else int(args.epochs)
    limit = args.limit_test or (2 if args.smoke else 0)
    train_n = 2 if args.smoke else s12.TRAIN_PER_CLASS
    calib_n = 1 if args.smoke else s12.CALIB_PER_CLASS

    splits = {}
    for item in items:
        paths = s12.train_good_paths(os.path.join(s12.DATA, item))
        train_p, calib_p = s12.split_train_calibration(paths, train_n, calib_n, SEED)
        splits[item] = {"train": train_p, "calib": calib_p}
        log(f"{item}: available={len(paths)} train={len(train_p)} calib={len(calib_p)}")

    cache = cache_train(model, items, splits, hi_tf, device,
                        os.path.join(OUT, "cache"))
    bank = build_knn_bank(cache, items, device,
                          per_class=8 if args.smoke else KNN_PER_CLASS)
    log(f"knn bank tokens={tuple(bank.shape)}")

    inp = INPLocalizer().to(device)
    inp_raw = INPLocalizer().to(device)
    hist = {
        "inp": train_localizer(inp, cache, device, True, epochs,
                               2 if args.smoke else args.train_batch, SEED),
        "inp_raw": train_localizer(inp_raw, cache, device, False, epochs,
                                   2 if args.smoke else args.train_batch, SEED),
    }
    s12.write_json_atomic(os.path.join(OUT, "history.json"), hist)
    torch.save({"inp": inp.state_dict(), "inp_raw": inp_raw.state_dict()},
               os.path.join(OUT, "inp_heads.pt"))

    stats = calibrate(items, splits, model, inp, inp_raw, bank, base_tf, hi_tf,
                      gaussian, device)
    per_class = {}
    for item in items:
        ds = s12.MultiScaleTestDataset(os.path.join(s12.DATA, item), base_tf,
                                       gt_tf, hi_tf)
        if limit:
            ds.base.img_paths = ds.base.img_paths[:limit]
            ds.base.gt_paths = ds.base.gt_paths[:limit]
            ds.base.labels = ds.base.labels[:limit]
            ds.base.types = ds.base.types[:limit]
        result, arrays = evaluate_class(
            item, ds, model, inp, inp_raw, bank, gaussian, stats[item], device)
        per_class[item] = result
        np.savez_compressed(os.path.join(OUT, f"{item}_preds.npz"),
                            gt=arrays["gt"], labels=arrays["labels"],
                            **{f"pred_{k}": v for k, v in arrays["preds"].items()})
        s12.write_json_atomic(os.path.join(OUT, f"{item}.json"), result)
        log(f"{item} P-AP " + " ".join(
            f"{k}={result['variants'][k]['metrics']['P-AP']:.4f}"
            for k in ("b0", "inp", "b0_inp", "b0_knn")))

    summary = aggregate(per_class, items)
    report = {
        "experiment": {"slug": SLUG, "stage": STAGE,
                       "plan": "experiment/READING_AND_STAGE13_PLAN.md"},
        "config": {
            "classes": items,
            "epochs": epochs,
            "prototypes": PROTO_NUM,
            "decoder_depth": DECODER_DEPTH,
            "knn_per_class": None if args.smoke else KNN_PER_CLASS,
            "fusion": "0.75*b0_norm+0.25*head_norm",
            "base_sha256": base_sha,
            "smoke": bool(args.smoke),
        },
        "per_class": per_class,
        "summary": summary,
    }
    s12.write_json_atomic(os.path.join(OUT, "prototype_report.json"), report)
    log(f"entry passed={summary['entry_condition']['passed']} "
        f"gain={summary['entry_condition']['b0_inp_minus_b0_P-AP']}")
    log("=== stage13 done ===")


if __name__ == "__main__":
    main()
